contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(
        string memory name_,
        string memory tokenURI,
        bool finiteSupply,
        bool transferable,
        uint256 itemsRemaining,
        uint256 itemPrice,
        uint16 dailyAllowance
    ) public {
        require(dailyAllowance > 0);
        require(bytes(tokenURI).length == 0);

        uint256 newId = c.uniqueTokensOutstanding(); if (__ESBMC_reverted()) return;

        c.createGameItem(name_, tokenURI, finiteSupply, transferable, itemsRemaining, itemPrice, dailyAllowance); if (__ESBMC_reverted()) return;

        uint256 remaining = c.getAllowanceRemaining(address(this), newId); if (__ESBMC_reverted()) return;

        assert(remaining == dailyAllowance);
    }

    receive() external payable {}
}

